import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2, FiEye, FiUsers } from 'react-icons/fi';
import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminCourses = () => {
  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    slug: '',
    description: '',
    long_description: '',
    duration: '',
    fee: 0,
    old_fee: 0,
    level: '',
    language: '',
    features: [],
    requirements: [],
    learning_outcomes: [],
    is_active: true,
    is_featured: false,
    is_popular: false,
    category_id: null,
    image: '',
    thumbnail: '',
    order: 0,
  });

  const levels = ['Beginner', 'Intermediate', 'Advanced'];
  const languages = ['Khmer', 'English', 'Both'];

  useEffect(() => {
    fetchCourses();
    fetchCategories();
  }, []);

  const fetchCourses = async () => {
    try {
      const response = await api.get('/api/courses/');
      setCourses(response.data);
    } catch (error) {
      toast.error('Failed to load courses');
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const response = await api.get('/api/courses/categories');
      setCategories(response.data);
    } catch (error) {
      console.error('Failed to load categories:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const dataToSend = {
        ...formData,
        features: formData.features.split(',').map(f => f.trim()).filter(f => f),
        requirements: formData.requirements.split(',').map(r => r.trim()).filter(r => r),
        learning_outcomes: formData.learning_outcomes.split(',').map(l => l.trim()).filter(l => l),
      };

      if (editingCourse) {
        await api.put(`/api/courses/${editingCourse.id}`, dataToSend);
        toast.success('Course updated successfully');
      } else {
        await api.post('/api/courses/', dataToSend);
        toast.success('Course created successfully');
      }
      setModalOpen(false);
      setEditingCourse(null);
      setFormData({
        title: '',
        slug: '',
        description: '',
        long_description: '',
        duration: '',
        fee: 0,
        old_fee: 0,
        level: '',
        language: '',
        features: [],
        requirements: [],
        learning_outcomes: [],
        is_active: true,
        is_featured: false,
        is_popular: false,
        category_id: null,
        image: '',
        thumbnail: '',
        order: 0,
      });
      fetchCourses();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this course?')) {
      try {
        await api.delete(`/api/courses/${id}`);
        toast.success('Course deleted successfully');
        fetchCourses();
      } catch (error) {
        toast.error('Failed to delete course');
      }
    }
  };

  const handleEdit = (course) => {
    setEditingCourse(course);
    setFormData({
      title: course.title,
      slug: course.slug,
      description: course.description || '',
      long_description: course.long_description || '',
      duration: course.duration || '',
      fee: course.fee || 0,
      old_fee: course.old_fee || 0,
      level: course.level || '',
      language: course.language || '',
      features: course.features?.join(', ') || '',
      requirements: course.requirements?.join(', ') || '',
      learning_outcomes: course.learning_outcomes?.join(', ') || '',
      is_active: course.is_active,
      is_featured: course.is_featured,
      is_popular: course.is_popular,
      category_id: course.category_id || null,
      image: course.image || '',
      thumbnail: course.thumbnail || '',
      order: course.order || 0,
    });
    setModalOpen(true);
  };

  const columns = [
    { key: 'title', label: 'Title' },
    { key: 'duration', label: 'Duration' },
    {
      key: 'fee',
      label: 'Fee ($)',
      render: (val) => `$${val.toFixed(2)}`,
    },
    { key: 'level', label: 'Level' },
    {
      key: 'is_active',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${
          val ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
        }`}>
          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button
            onClick={() => handleEdit(row)}
            className="text-blue-600 hover:text-blue-800"
          >
            <FiEdit2 />
          </button>
          <button
            onClick={() => handleDelete(row.id)}
            className="text-red-600 hover:text-red-800"
          >
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Courses Management</h1>
        <button
          onClick={() => {
            setEditingCourse(null);
            setFormData({
              title: '',
              slug: '',
              description: '',
              long_description: '',
              duration: '',
              fee: 0,
              old_fee: 0,
              level: '',
              language: '',
              features: [],
              requirements: [],
              learning_outcomes: [],
              is_active: true,
              is_featured: false,
              is_popular: false,
              category_id: null,
              image: '',
              thumbnail: '',
              order: 0,
            });
            setModalOpen(true);
          }}
          className="admin-btn-primary flex items-center space-x-2"
        >
          <FiPlus />
          <span>Add Course</span>
        </button>
      </div>

      <AdminCard>
        <AdminTable
          columns={columns}
          data={courses}
          loading={loading}
        />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          setEditingCourse(null);
        }}
        title={editingCourse ? 'Edit Course' : 'Create Course'}
        size="lg"
      >
        <form onSubmit={handleSubmit}>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="admin-label">Title *</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => {
                  setFormData({ 
                    ...formData, 
                    title: e.target.value,
                    slug: e.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-')
                  });
                }}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Slug *</label>
              <input
                type="text"
                value={formData.slug}
                onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Category</label>
              <select
                value={formData.category_id || ''}
                onChange={(e) => setFormData({ ...formData, category_id: parseInt(e.target.value) || null })}
                className="admin-input"
              >
                <option value="">Select Category</option>
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>{cat.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="admin-label">Duration</label>
              <input
                type="text"
                value={formData.duration}
                onChange={(e) => setFormData({ ...formData, duration: e.target.value })}
                className="admin-input"
                placeholder="3 months"
              />
            </div>
            <div>
              <label className="admin-label">Fee ($)</label>
              <input
                type="number"
                value={formData.fee}
                onChange={(e) => setFormData({ ...formData, fee: parseFloat(e.target.value) || 0 })}
                className="admin-input"
                step="0.01"
              />
            </div>
            <div>
              <label className="admin-label">Old Fee ($)</label>
              <input
                type="number"
                value={formData.old_fee}
                onChange={(e) => setFormData({ ...formData, old_fee: parseFloat(e.target.value) || 0 })}
                className="admin-input"
                step="0.01"
              />
            </div>
            <div>
              <label className="admin-label">Level</label>
              <select
                value={formData.level}
                onChange={(e) => setFormData({ ...formData, level: e.target.value })}
                className="admin-input"
              >
                <option value="">Select Level</option>
                {levels.map((level) => (
                  <option key={level} value={level}>{level}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="admin-label">Language</label>
              <select
                value={formData.language}
                onChange={(e) => setFormData({ ...formData, language: e.target.value })}
                className="admin-input"
              >
                <option value="">Select Language</option>
                {languages.map((lang) => (
                  <option key={lang} value={lang}>{lang}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="mt-4">
            <label className="admin-label">Description</label>
            <textarea
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="admin-input"
              rows="2"
            />
          </div>

          <div className="mt-4">
            <label className="admin-label">Long Description</label>
            <textarea
              value={formData.long_description}
              onChange={(e) => setFormData({ ...formData, long_description: e.target.value })}
              className="admin-input"
              rows="4"
            />
          </div>

          <div className="grid grid-cols-3 gap-4 mt-4">
            <div>
              <label className="admin-label">Features (comma separated)</label>
              <input
                type="text"
                value={formData.features}
                onChange={(e) => setFormData({ ...formData, features: e.target.value })}
                className="admin-input"
                placeholder="Feature 1, Feature 2"
              />
            </div>
            <div>
              <label className="admin-label">Requirements (comma separated)</label>
              <input
                type="text"
                value={formData.requirements}
                onChange={(e) => setFormData({ ...formData, requirements: e.target.value })}
                className="admin-input"
                placeholder="Requirement 1, Requirement 2"
              />
            </div>
            <div>
              <label className="admin-label">Learning Outcomes (comma separated)</label>
              <input
                type="text"
                value={formData.learning_outcomes}
                onChange={(e) => setFormData({ ...formData, learning_outcomes: e.target.value })}
                className="admin-input"
                placeholder="Outcome 1, Outcome 2"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 mt-4">
            <div>
              <label className="admin-label">Image URL</label>
              <input
                type="text"
                value={formData.image}
                onChange={(e) => setFormData({ ...formData, image: e.target.value })}
                className="admin-input"
                placeholder="https://example.com/image.jpg"
              />
            </div>
            <div>
              <label className="admin-label">Thumbnail URL</label>
              <input
                type="text"
                value={formData.thumbnail}
                onChange={(e) => setFormData({ ...formData, thumbnail: e.target.value })}
                className="admin-input"
                placeholder="https://example.com/thumbnail.jpg"
              />
            </div>
          </div>

          <div className="flex flex-wrap gap-4 mt-4">
            <label className="flex items-center space-x-2">
              <input
                type="checkbox"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
              />
              <span>Active</span>
            </label>
            <label className="flex items-center space-x-2">
              <input
                type="checkbox"
                checked={formData.is_featured}
                onChange={(e) => setFormData({ ...formData, is_featured: e.target.checked })}
              />
              <span>Featured</span>
            </label>
            <label className="flex items-center space-x-2">
              <input
                type="checkbox"
                checked={formData.is_popular}
                onChange={(e) => setFormData({ ...formData, is_popular: e.target.checked })}
              />
              <span>Popular</span>
            </label>
          </div>

          <div className="mt-6 flex justify-end space-x-3">
            <button
              type="button"
              onClick={() => {
                setModalOpen(false);
                setEditingCourse(null);
              }}
              className="admin-btn-secondary"
            >
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingCourse ? 'Update' : 'Create'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminCourses;
